export function Conversation({
  userText = "{{userText}}",
  aiText = "{{aiText}}",
  accent = "{{accent}}",
  bubbleShape = "{{bubbleShape}}",
  showAvatars = {{showAvatars}},
}) {
  const radius = { rounded: 14, sharp: 4, pill: 999 }[bubbleShape] ?? 14;
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 14, lineHeight: 1.5, color: "#241430",
      background: "#FAF7F2", maxWidth: 380, padding: 16, borderRadius: 14, boxSizing: "border-box" }}>
      <div style={{ display: "flex", alignItems: "flex-end", gap: 8, marginBottom: 10, flexDirection: "row-reverse" }}>
        {showAvatars && <span aria-hidden="true" style={{ flex: "none", width: 24, height: 24, borderRadius: "50%",
          display: "flex", alignItems: "center", justifyContent: "center", fontSize: 10, fontWeight: 700, color: "#FAF7F2", background: "#241430" }}>U</span>}
        <p style={{ margin: 0, padding: "10px 14px", maxWidth: "78%", borderRadius: radius, background: accent, color: "#241430", boxSizing: "border-box" }}>{userText}</p>
      </div>
      <div style={{ display: "flex", alignItems: "flex-end", gap: 8 }}>
        {showAvatars && <span aria-hidden="true" style={{ flex: "none", width: 24, height: 24, borderRadius: "50%",
          display: "flex", alignItems: "center", justifyContent: "center", fontSize: 10, fontWeight: 700, color: "#241430", background: accent }}>AI</span>}
        <p style={{ margin: 0, padding: "10px 14px", maxWidth: "78%", borderRadius: radius, background: "#24143010", boxSizing: "border-box" }}>{aiText}</p>
      </div>
    </div>
  );
}
